for (auto folder : allDescendants) {
  // Can't compact virtual folders.
  uint32_t flags;
  folder->GetFlags(&flags);
  if (flags & nsMsgFolderFlags::Virtual) {
    continue;
  }

  // If folder doesn't currently have a DB, expungedBytes might be out of
  // whack. Also the compact might do a folder reparse first, which could
  // change the expungedBytes count (via Expunge flag in
  // X-Mozilla-Status).
  bool hasDB;
  folder->GetDatabaseOpen(&hasDB);

  expungedBytes = 0;
  if (folder) rv = folder->GetExpungedBytes(&expungedBytes);

  NS_ENSURE_SUCCESS(rv, rv);

  if (!hasDB || expungedBytes > 0) folderArray.AppendElement(folder);

// Filter out noncompactable folders and ones with zero .expungedBytes.
nsTArray<RefPtr<nsIMsgFolder>> filteredFolders;
for (nsIMsgFolder* f : folders) {
  // Get expunged count.
  int64_t expunged = 0;
  nsresult rv = f->GetExpungedBytes(&expunged);
  NS_ENSURE_SUCCESS(rv, rv);
  if (expunged == 0) {
    MOZ_LOG(
        gCompactLog, LogLevel::Info,
        ("AsyncCompactFolders() ignoring folder '%s' (expungedBytes is 0)",
         f->URI().get()));
    continue;  // Skip it.
  }

  // Supports compaction?
  bool supportsCompaction;
  nsCOMPtr<nsIMsgPluggableStore> msgStore;
  rv = f->GetMsgStore(getter_AddRefs(msgStore));
  NS_ENSURE_SUCCESS(rv, rv);
  rv = msgStore->GetSupportsCompaction(&supportsCompaction);
  NS_ENSURE_SUCCESS(rv, rv);
  if (!supportsCompaction) {
    MOZ_LOG(gCompactLog, LogLevel::Info,
            ("AsyncCompactFolders() ignoring folder '%s' (compaction "
             "unsupported)",
             f->URI().get()));
    continue;  // Skip it.
  }

  // If we get this far, we'll compact it!
  filteredFolders.AppendElement(f);
